        const val = usdValue - (algoTotalImpactCost + algoTotalGas);
        finalReceive = formatMoney(val);
        receiveValNum = val;
    } else {
        const val = usdValue * (1 - swapImpactPct/100);
        finalReceive = formatMoney(val);
        receiveValNum = val;
