              >
                Swap
              </button>

              <button 
                onClick={() => setTradeMode('limit')}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${tradeMode === 'limit' ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
              >
                Limit
              </button>

              {/* ALGO TAB */}
              <button 
                onClick={() => setTradeMode('algo')}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 relative ${tradeMode === 'algo' ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
              >
                <Ghost size={12} /> 
                <span>Algo</span>
              </button>
            </div>

            {/* SETTINGS */}
            <div className="flex items-center gap-6">
                <button className="bg-zinc-800 p-2.5 rounded-xl border border-white/5 text-gray-500 hover:text-white cursor-pointer transition-colors outline-none hover:bg-zinc-700">
                    <Settings size={18} aria-hidden="true" />
                </button>
            </div>
          </div>

          {/* INPUT FORM */}
          {tradeMode === 'algo' && isAlgoRunning ? (
             <div className="space-y-6 py-4 animate-in fade-in zoom-in-95 duration-500 flex-1 flex flex-col">
                <div className="flex items-center justify-between">
                   <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                     <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                     Execution Active
                   </span>
                   <span className="text-[10px] font-mono font-bold text-purple-400 tabular-nums">{algoStrategy} • {algoDuration}H</span>
                </div>

                <div className="bg-black/40 border border-white/5 rounded-3xl p-6 relative overflow-hidden">
