                        className="text-[9px] font-black text-emerald-500 hover:text-emerald-400 uppercase tracking-widest bg-emerald-500/10 px-2.5 py-2 rounded-lg border border-emerald-500/20 transition-all active:scale-95"
                    >
                        Max
                    </button>
                  </EducationalTooltip>
                  <button className="flex items-center space-x-2 bg-zinc-800 border border-white/10 px-3 py-2 rounded-xl hover:bg-zinc-700 transition-all shadow-inner shrink-0 min-w-[100px]">
                    <div className="w-5 h-5 rounded-full bg-indigo-600 flex items-center justify-center border border-white/5 overflow-hidden">
                      <img src={ETH_ICON} alt="ETH" className="w-full h-full object-contain p-0.5" />
                    </div>
                    <span className="text-sm font-bold">ETH</span>
                    <ChevronDown size={14} className="text-gray-500 ml-auto" />
                  </button>
                </div>
              </div>

              {/* Fiat Subtext */}
              <div className="mt-2 text-[10px] font-mono font-medium text-zinc-500">
                  ≈ {formatMoney(numericPay * ETH_PRICE)}
              </div>
            </div>

            {/* SWAP DIRECTION ARROW (ABSOLUTE CENTERED) - Fixed alignment */}
            {tradeMode === 'market' && (
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-10">
                    <button 
                        className="w-10 h-10 bg-zinc-900 border border-white/10 rounded-xl flex items-center justify-center text-emerald-500 shadow-xl ring-8 ring-[#0a0a0a] hover:rotate-180 hover:border-emerald-500 hover:bg-white/10 transition-all duration-500 active:scale-90"
                    >
                        <ArrowDown size={18} strokeWidth={2.5} />
                    </button>
                </div>
            )}

            {/* CONDITIONAL INPUT: LIMIT PRICE */}
            {tradeMode === 'limit' && (
                <div className={`bg-black/40 border rounded-xl p-5 focus-within:border-blue-500/50 transition-all animate-in slide-in-from-top-2 h-[120px] flex flex-col justify-center ${simulation.isBelowMarketSell ? 'border-orange-500/40' : 'border-blue-500/20'}`}>
                    <div className="flex justify-between items-center mb-4">
                        <label className={`text-[10px] font-bold uppercase tracking-[0.2em] flex items-center gap-2 ${simulation.isBelowMarketSell ? 'text-orange-500' : 'text-gray-500'}`}>
                           LIMIT PRICE (PER TOKEN) {simulation.isBelowMarketSell && <AlertTriangle size={12} className="animate-pulse" />}
                        </label>
                        <div className="flex items-center gap-2">
                           {/* DYNAMIC SHORTCUTS: Selling ETH -> Higher is better */}
                           <button onClick={() => adjustLimitPrice(0)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors uppercase">Market</button>
                           <button onClick={() => adjustLimitPrice(1)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors">+1%</button>
                           <button onClick={() => adjustLimitPrice(5)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors">+5%</button>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                         <span className={`text-2xl font-bold ${simulation.isBelowMarketSell ? 'text-orange-500' : 'text-gray-500'}`}>$</span>
                         <input 
                            type="text"
                            value={limitPrice}
                            onChange={(e) => setLimitPrice(e.target.value)}
                            className={`bg-transparent text-2xl lg:text-3xl font-mono font-bold focus:outline-none w-full tracking-tighter tabular-nums ${simulation.isBelowMarketSell ? 'text-orange-400' : 'text-blue-400'}`}
                         />
                         <div className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest bg-zinc-800/50 px-3 py-2 rounded-lg border border-white/5">
                            USDC
                         </div>
                    </div>
                </div>
            )}

            {/* CONFIGURATION AREA (ALGO) */}
            {tradeMode === 'algo' ? (
               <div className="space-y-4 animate-in slide-in-from-bottom-2 flex-1">

                  {/* Strategy Tabs */}
                  <div className="grid grid-cols-3 gap-3">
                     {['TWAP', 'VWAP', 'ICEBERG'].map(strat => (
                        <button 
