                           className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${algoStrategy === strat ? 'bg-purple-500 text-white border-purple-500 shadow-lg shadow-purple-500/20' : 'bg-zinc-800/50 text-zinc-500 border-white/5 hover:bg-zinc-800'}`}
                        >
                           {strat}
                        </button>
                     ))}
                  </div>

                  {/* PRICE PROTECTION */}
                  <div className="bg-black/40 border border-white/5 rounded-xl p-4 flex items-center justify-between">
                      <div className="flex flex-col">
                          <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Min. Sell Price</label>
                          <div className="flex items-center gap-2">
                              <span className="text-zinc-600 font-bold">$</span>
                              <input 
                                  type="text" 
