                                  placeholder="No Limit"
                                  className="bg-transparent text-sm font-mono font-bold text-white outline-none w-24 placeholder:text-zinc-700"
                              />
                          </div>
                      </div>
                      <div className="p-2 bg-zinc-800 rounded-lg text-zinc-500">
                          <Shield size={16} />
                      </div>
                  </div>

                  {/* DURATION SLIDER + INPUT */}
                  <div className="bg-zinc-900/50 p-5 rounded-xl border border-white/5">
                     <div className="flex justify-between items-center mb-4">
                        <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Execution Duration (Hrs)</span>
                        <input 
                            type="number" 
                            value={algoDuration}
                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                            className="bg-zinc-950 border border-white/10 rounded-lg w-16 text-center text-xs font-mono font-bold text-white py-1 outline-none focus:border-purple-500"
                        />
                     </div>

                     <div className="relative h-4 w-full flex items-center">
                        <input 
                            type="range" 
                            min="0.5" 
                            max="24" 
                            step="0.5"
                            value={algoDuration} 
                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                            className="w-full h-1 bg-zinc-700 rounded-full appearance-none cursor-pointer accent-purple-500"
                            style={{ height: '4px' }}
                        />
                     </div>

                     <div className="mt-4 flex items-center justify-between border-t border-white/5 pt-3">
                         <div className="flex items-center gap-1.5 text-[9px] font-bold text-purple-400 uppercase tracking-wide">
                             <Split size={12} />
                             <span>{simulation.numTranches} Tranches</span>
                         </div>
                         <div className="text-[9px] font-mono text-zinc-500 tabular-nums">
                             ~1 tx every {simulation.avgIntervalMins} mins
                         </div>
                     </div>
                  </div>

                  {/* RANDOMIZE (Outline Icon) */}
                  <div 
                     onClick={() => setAlgoRandomize(!algoRandomize)}
                     className={`p-4 rounded-xl border cursor-pointer transition-all flex items-center justify-between group ${algoRandomize ? 'bg-purple-500/10 border-purple-500/30' : 'bg-zinc-900/50 border-white/5'}`}
                  >
                     <div className="flex items-center gap-3">
                        <Shuffle size={20} strokeWidth={1.5} className="text-gray-500 group-hover:text-gray-300" />
                        <div>
                           <p className={`text-[10px] font-black uppercase tracking-widest ${algoRandomize ? 'text-purple-300' : 'text-zinc-500'}`}>Randomize Intervals</p>
                           <p className="text-[10px] text-zinc-500 leading-tight">Sandwich Protection</p>
                        </div>
                     </div>
                     <div className={`w-10 h-5 rounded-full relative transition-colors ${algoRandomize ? 'bg-purple-500' : 'bg-zinc-700'}`}>
                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all duration-300 ${algoRandomize ? 'left-6' : 'left-1'}`}></div>
                     </div>
                  </div>
               </div>
            ) : tradeMode === 'limit' ? (
                // LIMIT SETTINGS
                <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-bottom-2">
                    <div className="bg-black/40 border border-white/5 rounded-xl p-4 flex flex-col justify-between group focus-within:border-blue-500/30 transition-colors">
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5 group-hover:text-zinc-300 transition-colors">
                            <Clock size={10} /> Expiry
                         </span>
                         <select 
                            value={expiry} 
                            onChange={(e) => setExpiry(e.target.value)}
                            className="bg-transparent text-sm font-bold text-white outline-none cursor-pointer"
                         >
                            <option value="10m">10 Minutes</option>
                            <option value="1h">1 Hour</option>
                            <option value="24h">24 Hours</option>
                            <option value="3d">3 Days</option>
                            <option value="7d">7 Days</option>
                            <option value="GTC">Never (GTC)</option>
                         </select>
                    </div>

                    <div 
                       onClick={() => setPostOnly(!postOnly)}
                       className={`bg-black/40 border rounded-xl p-4 flex flex-col justify-between cursor-pointer transition-colors ${postOnly ? 'border-emerald-500/30 bg-emerald-500/5' : 'border-white/5 hover:bg-zinc-900'}`}
                    >
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center justify-between">
                            <span>Post-Only</span>
                            {postOnly ? <CheckSquare size={12} className="text-emerald-500" /> : <Square size={12} />}
                         </span>
                         <span className={`text-xs font-bold ${postOnly ? 'text-emerald-500' : 'text-zinc-400'}`}>
                             {postOnly ? 'Maker Guaranteed' : 'Standard'}
                         </span>
