            ) : null}

            {/* BLOCK 3: RECEIVE AMOUNT */}
            {(tradeMode === 'market' || tradeMode === 'limit') && (
                <div className="bg-black/40 border border-white/5 rounded-xl p-5 transition-all min-h-[140px] flex flex-col justify-center">
