// --- STRICT FORMATTING HELPERS (US LOCALE) ---
// Used for Fiat Prices (Rates)
const formatMoney = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
// Used for Token Amounts (No $)
const formatToken = (val: number) => new Intl.NumberFormat('en-US', { minimumFractionDigits: 4, maximumFractionDigits: 4 }).format(val);
const formatTokenAmount = (val: number) => new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(val);
const formatPercent = (val: number) => `${val > 0 ? '+' : ''}${val.toFixed(2)}%`;

// Helper for precision impact display
const formatImpactPercent = (val: number) => {
    if (val > 0 && val < 0.01) return '< 0.01%';
    if (val === 0) return '0.00%';
    return `~${val.toFixed(2)}%`;
};

// --- EDUCATIONAL TOOLTIP COMPONENT (3s DELAY) ---
interface EducationalTooltipProps {
  title: string;
  desc: string;
  children: React.ReactNode;
}

const EducationalTooltip: React.FC<EducationalTooltipProps> = ({ title, desc, children }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [coords, setCoords] = useState({ top: 0, left: 0 });
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const triggerRef = useRef<HTMLDivElement>(null);

  const handleMouseEnter = () => {
    timerRef.current = setTimeout(() => {
      if (triggerRef.current) {
        const rect = triggerRef.current.getBoundingClientRect();
        setCoords({
          top: rect.top + window.scrollY, 
          left: rect.left + rect.width / 2
        });
        setIsVisible(true);
      }
    }, 3000); 
  };

  const handleMouseLeave = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    setIsVisible(false);
  };

  return (
    <>
      <div 
        ref={triggerRef} 
        onMouseEnter={handleMouseEnter} 
        onMouseLeave={handleMouseLeave} 
        className="cursor-help w-full h-full block"
      >
        {children}
      </div>
      {isVisible && createPortal(
        <div 
          className="fixed z-[9999] pointer-events-none animate-in fade-in zoom-in-95 duration-300"
          style={{ 
            top: coords.top - 12, 
            left: coords.left, 
            transform: 'translate(-50%, -100%)' 
          }}
        >
          <div className="w-[280px] bg-zinc-900/95 border border-white/10 backdrop-blur-md p-5 rounded-xl shadow-2xl relative">
             <h4 className="text-white font-bold text-xs uppercase tracking-wider mb-2 flex items-center gap-2">
                <Sparkles size={12} className="text-emerald-500" />
                {title}
             </h4>
             <p className="text-zinc-300 text-[11px] leading-relaxed font-medium">{desc}</p>
             {/* Arrow */}
             <div className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 w-3 h-3 bg-zinc-900/95 border-b border-r border-white/10 rotate-45"></div>
          </div>
        </div>,
        document.body
      )}
    </>
  );
};

const ExecutionView: React.FC = () => {
  // --- STATE ---
  const [payAmount, setPayAmount] = useState('');
  const [tradeMode, setTradeMode] = useState<'market' | 'limit' | 'algo'>('market');

  // Settings
  const [slippage, setSlippage] = useState(0.5);

  // Limit Specific State
  const [limitPrice, setLimitPrice] = useState('3208.93');
  const [expiry, setExpiry] = useState('24h');
  const [postOnly, setPostOnly] = useState(false);

  // Algo Specific State
  const [algoDuration, setAlgoDuration] = useState(4); // Hours
  const [algoMinPrice, setAlgoMinPrice] = useState(''); // Price Protection
  const [algoStrategy, setAlgoStrategy] = useState<'TWAP' | 'VWAP' | 'ICEBERG'>('TWAP');
  const [algoRandomize, setAlgoRandomize] = useState(false);
  const [isAlgoRunning, setIsAlgoRunning] = useState(false);
  const [executionProgress, setExecutionProgress] = useState(0);

  // --- CONSTANTS ---
  const ETH_PRICE = 3208.93;
  const ETH_BALANCE = 350.0000; 
  const BASE_GAS_COST_USD = 9.75; 
  const MIN_TRANCHE_USD = 2000; 
  const GAS_RESERVE = 0.01; // ETH to reserve

  // Limit Chart Constants
  const SUPPORT_LEVEL = 3180.00;
  const RESISTANCE_LEVEL = 3280.00;
  const RISK_FREE_RATE = 0.042;

  const USDC_ICON = 'https://cryptologos.cc/logos/usd-coin-usdc-logo.png?v=035';
  const ETH_ICON = 'https://cryptologos.cc/logos/ethereum-eth-logo.png?v=035';

  // --- CORE ENGINE CALCULATIONS ---

  // Error State Logic
  const numericPay = parseFloat(payAmount) || 0;
  const isInsufficientBalance = numericPay > ETH_BALANCE;

  const simulation = useMemo(() => {
    const pay = numericPay;
    const usdValue = pay * ETH_PRICE; 
    const limitP = parseFloat(limitPrice) || ETH_PRICE;
    const limitValue = pay * limitP; 

    // 1. SWAP IMPACT SIMULATION
    let swapImpactPct = 0;
    if (usdValue > 0) {
        swapImpactPct = Math.min(Math.pow(usdValue / 1_000_000, 1.2) * 0.45, 15);
    }
    const swapImpactCost = usdValue * (swapImpactPct / 100);

    // 2. ALGO TRANCHING LOGIC
    const maxViableTranches = Math.floor(usdValue / MIN_TRANCHE_USD);
    const totalMinutes = algoDuration * 60;
    let optimalTranches = Math.floor(totalMinutes / 20); 
    if (optimalTranches > maxViableTranches) optimalTranches = Math.max(1, maxViableTranches);
    if (optimalTranches < 1) optimalTranches = 1;
    if (usdValue === 0) optimalTranches = 0;

    const trancheSizeETH = optimalTranches > 0 ? pay / optimalTranches : 0;
    const avgIntervalMins = optimalTranches > 0 ? Math.floor(totalMinutes / optimalTranches) : 0;
    // Algo impact is much lower per tranche
    const algoTrancheImpactPct = Math.min(Math.pow((usdValue/optimalTranches) / 1_000_000, 1.2) * 0.45, 15);
    const algoTotalImpactCost = usdValue * (algoTrancheImpactPct / 100);
    const algoTotalGas = optimalTranches * BASE_GAS_COST_USD;
    const swapTotalGas = BASE_GAS_COST_USD; 

    const totalSwapCost = swapImpactCost + swapTotalGas;
    const totalAlgoCost = algoTotalImpactCost + algoTotalGas;
    const netSavings = totalSwapCost - totalAlgoCost;
    const isAlgoEfficient = netSavings > 0;

    // 3. MARKET INTELLIGENCE
    const routingScore = 9.9;

    const routeSplit = [
        { dex: 'Uniswap V3', pct: 65, color: 'bg-white' }, 
        { dex: 'Curve', pct: 25, color: 'bg-zinc-600' },
        { dex: 'SushiSwap', pct: 10, color: 'bg-zinc-700' }
    ];

    // 4. LIMIT INTELLIGENCE
    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isBelowMarketSell = distanceToMarket < 0; 

    let execProbability = 0;
    let probLabel = 'LOW';
    let probColor = 'text-zinc-500';
    let timeHorizon = '> 4 Days';
    let timeRange = '3d - 7d';

    if (isBelowMarketSell) {
        execProbability = 100;
        probLabel = 'IMMEDIATE';
        probColor = 'text-orange-500';
        timeHorizon = 'Instant';
        timeRange = 'Now';
    } else {
        if (distanceToMarket < 0.5) {
            execProbability = 92;
            probLabel = 'VERY HIGH';
            probColor = 'text-emerald-400';
            timeHorizon = '< 1 Hour';
            timeRange = '10m - 90m';
        } else if (distanceToMarket < 1.5) {
            execProbability = 75;
            probLabel = 'HIGH';
            probColor = 'text-emerald-500';
            timeHorizon = '~12 Hours';
            timeRange = '4h - 24h';
        } else if (distanceToMarket < 3.0) {
            execProbability = 45;
            probLabel = 'MEDIUM';
            probColor = 'text-amber-500';
            timeHorizon = '~2 Days';
            timeRange = '12h - 4d';
        } else {
            execProbability = 12;
            probLabel = 'LOW';
            probColor = 'text-rose-500';
            timeHorizon = '> 4 Days';
            timeRange = '3d - GTC';
        }
    }

    const dailyYieldLoss = (limitValue * RISK_FREE_RATE) / 365;
    const wallsAheadUsd = Math.abs(distanceToMarket) * 8_000_000; 

    // Structure Analysis
    let structureLabel = 'IN RANGE';
    let structureColor = 'text-zinc-400';
    if (limitP < SUPPORT_LEVEL) {
        structureLabel = 'BELOW SUPPORT'; 
        structureColor = 'text-orange-400';
    } else if (limitP > RESISTANCE_LEVEL) {
        structureLabel = 'BREAKOUT TARGET';
        structureColor = 'text-emerald-400'; 
    }

    // 5. CHART DATA (Schedule)
    const scheduleData = [];
    if (optimalTranches > 0) {
        let currentTime = new Date();
        const now = new Date();
        const startTime = new Date(now.getTime() - (avgIntervalMins * 60000 * 2)); 
        currentTime = startTime;

        for (let i = 0; i < optimalTranches; i++) {
             let variance = 1;
             if (algoRandomize) variance = 0.8 + Math.random() * 0.4; 

             let status: 'executed' | 'active' | 'pending' = 'pending';
             if (i < 2) status = 'executed';
             if (i === 2) status = 'active';

             scheduleData.push({
                 id: i,
                 time: currentTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
                 volume: trancheSizeETH * variance,
                 status: status
             });
             currentTime = new Date(currentTime.getTime() + avgIntervalMins * 60000);
        }
    }

    // 6. RECEIVE AMOUNT (NO $)
    let finalReceive = '0.00';
    let receiveValNum = 0;

    if (tradeMode === 'limit') {
        finalReceive = formatTokenAmount(limitValue);
        receiveValNum = limitValue;
    } else if (tradeMode === 'algo') {
        const val = usdValue - (algoTotalImpactCost + algoTotalGas);
        finalReceive = formatTokenAmount(val);
        receiveValNum = val;
    } else {
        const val = usdValue * (1 - swapImpactPct/100);
        finalReceive = formatTokenAmount(val);
        receiveValNum = val;
    }

    return {
        usdValue,
        limitValue,
        receiveAmount: finalReceive,
        receiveValNum,
        swapImpactPct,
        swapImpactCost,
        algoTrancheImpactPct,
        algoTotalImpactCost,
        numTranches: optimalTranches,
        avgIntervalMins,
        algoTotalGas,
        swapTotalGas,
        netSavings,
        isAlgoEfficient,
        scheduleData,
        routingScore,
        routeSplit,
        totalSwapCost,
        distanceToMarket,
        isBelowMarketSell,
        execProbability,
        probLabel,
        probColor,
        timeHorizon,
        timeRange,
        dailyYieldLoss,
        structureLabel,
        structureColor,
        wallsAheadUsd,
        liquidityBuffer: `${slippage}%`
    };
  }, [payAmount, tradeMode, algoDuration, limitPrice, algoRandomize, slippage]);


  // --- HANDLERS ---
  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '' || /^\d*\.?\d*$/.test(val)) {
      setPayAmount(val);
    }
  };

  const handleMaxClick = () => {
    // Gas Reserve Logic
    const max = Math.max(0, ETH_BALANCE - GAS_RESERVE);
    setPayAmount(max.toFixed(4));
  };

  const adjustLimitPrice = (pct: number) => {
      const newPrice = pct === 0 ? ETH_PRICE : ETH_PRICE * (1 + pct / 100);
      setLimitPrice(newPrice.toFixed(2));
  };

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isAlgoRunning && executionProgress < 100) {
      interval = setInterval(() => {
        setExecutionProgress(prev => Math.min(prev + 0.5, 100));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isAlgoRunning, executionProgress]);


  // --- VISUALIZATION DATA ---

  // 1. Structure Chart (Limit V3.1)
  const structureData = useMemo(() => {
      const data = [];
      let currentP = 3195; 
      for(let i=0; i<=20; i++) {
          if (i === 20) {
             data.push({ i, price: ETH_PRICE }); 
          } else {
             currentP = currentP + (Math.random() * 30 - 12);
             data.push({ i, price: currentP });
          }
      }
      return data;
  }, []);

  // 2. Depth Chart Data (Limit V3.1) - Stepped Walls
  const depthData = useMemo(() => {
      const data = [];
      const limitP = parseFloat(limitPrice) || ETH_PRICE;
      const startPrice = ETH_PRICE * 0.95;
      const endPrice = ETH_PRICE * 1.05;
      const steps = 40; 
      const stepSize = (endPrice - startPrice) / steps;

      for(let i = 0; i <= steps; i++) {
          const p = startPrice + (i * stepSize);
          let bidVol = 0;
          let askVol = 0;
          if (p < ETH_PRICE) {
             const dist = ETH_PRICE - p;
             bidVol = 5000;
             if (dist > 10) bidVol += 25000;
             if (dist > 30) bidVol += 55000;
             if (dist > 60) bidVol += 120000;
          }
          if (p > ETH_PRICE) {
             const dist = p - ETH_PRICE;
             askVol = 5000;
             if (dist > 15) askVol += 35000;
             if (dist > 40) askVol += 75000;
             if (dist > 80) askVol += 150000;
          }
          data.push({ price: p, bidVol, askVol });
      }
      return data;
  }, [limitPrice]);

  return (
