                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                            className="bg-zinc-950 border border-white/10 rounded-lg w-16 text-center text-xs font-mono font-bold text-white py-1 outline-none focus:border-purple-500"
                        />
                     </div>

                     <div className="relative h-4 w-full flex items-center">
                        <input 
                            type="range" 
                            min="0.5" 
                            max="24" 
                            step="0.5"
                            value={algoDuration} 
                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                            className="w-full h-1 bg-zinc-700 rounded-full appearance-none cursor-pointer accent-purple-500"
                            style={{ height: '4px' }}
                        />
                     </div>

                     <div className="mt-4 flex items-center justify-between border-t border-white/5 pt-3">
                         <div className="flex items-center gap-1.5 text-[9px] font-bold text-purple-400 uppercase tracking-wide">
                             <Split size={12} />
                             <span>{simulation.numTranches} Tranches</span>
                         </div>
                         <div className="text-[9px] font-mono text-zinc-500 tabular-nums">
                             ~1 tx every {simulation.avgIntervalMins} mins
                         </div>
                     </div>
                  </div>

                  {/* RANDOMIZE (Outline Icon) */}
                  <div 
                     onClick={() => setAlgoRandomize(!algoRandomize)}
                     className={`p-4 rounded-xl border cursor-pointer transition-all flex items-center justify-between group ${algoRandomize ? 'bg-purple-500/10 border-purple-500/30' : 'bg-zinc-900/50 border-white/5'}`}
                  >
                     <div className="flex items-center gap-3">
                        <Shuffle size={20} strokeWidth={1.5} className="text-gray-500 group-hover:text-gray-300" />
                        <div>
                           <p className={`text-[10px] font-black uppercase tracking-widest ${algoRandomize ? 'text-purple-300' : 'text-zinc-500'}`}>Randomize Intervals</p>
                           <p className="text-[10px] text-zinc-500 leading-tight">Sandwich Protection</p>
                        </div>
                     </div>
                     <div className={`w-10 h-5 rounded-full relative transition-colors ${algoRandomize ? 'bg-purple-500' : 'bg-zinc-700'}`}>
                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all duration-300 ${algoRandomize ? 'left-6' : 'left-1'}`}></div>
                     </div>
                  </div>
               </div>
            ) : tradeMode === 'limit' ? (
                // LIMIT SETTINGS
                <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-bottom-2">
                    <div className="bg-black/40 border border-white/5 rounded-xl p-4 flex flex-col justify-between group focus-within:border-blue-500/30 transition-colors">
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5 group-hover:text-zinc-300 transition-colors">
                            <Clock size={10} /> Expiry
                         </span>
                         <select 
                            value={expiry} 
                            onChange={(e) => setExpiry(e.target.value)}
                            className="bg-transparent text-sm font-bold text-white outline-none cursor-pointer"
                         >
                            <option value="10m">10 Minutes</option>
                            <option value="1h">1 Hour</option>
                            <option value="24h">24 Hours</option>
                            <option value="3d">3 Days</option>
                            <option value="7d">7 Days</option>
                            <option value="GTC">Never (GTC)</option>
                         </select>
                    </div>

                    <div 
                       onClick={() => setPostOnly(!postOnly)}
                       className={`bg-black/40 border rounded-xl p-4 flex flex-col justify-between cursor-pointer transition-colors ${postOnly ? 'border-emerald-500/30 bg-emerald-500/5' : 'border-white/5 hover:bg-zinc-900'}`}
                    >
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center justify-between">
                            <span>Post-Only</span>
                            {postOnly ? <CheckSquare size={12} className="text-emerald-500" /> : <Square size={12} />}
                         </span>
                         <span className={`text-xs font-bold ${postOnly ? 'text-emerald-500' : 'text-zinc-400'}`}>
                             {postOnly ? 'Maker Guaranteed' : 'Standard'}
                         </span>
                    </div>
                </div>
            ) : null}

            {/* BLOCK 3: RECEIVE AMOUNT */}
            {(tradeMode === 'market' || tradeMode === 'limit') && (
                <div className="bg-black/40 border border-white/5 rounded-xl p-5 transition-all min-h-[140px] flex flex-col justify-center">
                    <div className="flex justify-between items-center mb-4">
                        <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em]">YOU RECEIVE</label>
                    </div>
                    <div className="flex justify-between items-center gap-4">
                        <span className={`text-3xl font-mono font-bold tracking-tighter tabular-nums ${numericPay > 0 ? 'text-white' : 'text-zinc-700'}`}>
                            {numericPay > 0 ? formatTokenAmount(simulation.receiveValNum) : '0.00'}
                        </span>
                        <button className="flex items-center space-x-2 bg-zinc-800 border border-white/10 px-3 py-2 rounded-xl hover:bg-zinc-700 transition-all shadow-inner shrink-0 min-w-[100px]">
                        <div className="w-5 h-5 rounded-full bg-blue-600 flex items-center justify-center shadow-lg shadow-blue-500/20 overflow-hidden border border-white/5">
                            <img src={USDC_ICON} alt="USDC" className="w-full h-full object-contain p-0.5" />
                        </div>
                        <span className="text-sm font-bold">USDC</span>
                        <ChevronDown size={14} className="text-gray-500 ml-auto" />
                        </button>
                    </div>
                    {/* Fiat Subtext */}
                    <div className="mt-2 text-[10px] font-mono font-medium text-zinc-500">
                        ≈ {formatMoney(simulation.receiveValNum)}
                    </div>
                </div>
            )}

          </div>
          )}

          {/* FOOTER: COSTS & CTA */}
          <div className="mt-auto pt-6">
             <div className="space-y-3 bg-zinc-900/40 p-5 rounded-2xl border border-white/5">
                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest">
                  <span className="text-zinc-500 font-bold">Market Rate</span>
                  <span className="text-zinc-100 font-mono font-bold tabular-nums">1 ETH = {formatMoney(ETH_PRICE)}</span>
                </div>

                {tradeMode === 'algo' ? (
                    <div className="flex justify-between items-center text-[10px] uppercase tracking-widest">
                      <span className="text-zinc-500 font-bold">Strategy Variance</span>
                      <span className="text-purple-400 font-mono font-bold tabular-nums">{formatImpactPercent(simulation.algoTrancheImpactPct)} (VWAP)</span>
                    </div>
                ) : tradeMode === 'limit' ? (
                    <div className="flex justify-between items-center text-[10px] uppercase tracking-widest">
                      <span className="text-zinc-500 font-bold">Distance to Market</span>
                      <span className={`font-mono font-bold tabular-nums ${simulation.distanceToMarket > 0 ? 'text-emerald-500' : 'text-orange-500'}`}>
                          {simulation.distanceToMarket > 0 ? '+' : ''}{simulation.distanceToMarket.toFixed(2)}%
                      </span>
                    </div>
                ) : null}

                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest pt-3 border-t border-white/5">
                  <span className="text-zinc-500 font-bold flex items-center gap-1">
                      <Fuel size={10} className="text-gray-500" /> {tradeMode === 'algo' ? 'Est. Total Gas' : 'Network Fee'}
                  </span>
                  <div className="text-right">
                     {tradeMode === 'limit' ? (
                        <span className="text-blue-400 font-bold flex items-center gap-1 justify-end">
                            <MousePointerClick size={10} /> FREE (Signature)
                        </span>
                     ) : (
                        <span className={`font-mono font-bold tabular-nums text-zinc-300`}>
                            ~{tradeMode === 'algo' ? formatMoney(simulation.algoTotalGas) : formatMoney(simulation.swapTotalGas)}
                        </span>
                     )}
                  </div>
                </div>
             </div>

             {/* MAIN CTA BUTTON: Rounded-xl, White Text */}
             <button 
                onClick={tradeMode === 'algo' ? () => setIsAlgoRunning(true) : undefined}
                disabled={numericPay <= 0 || isInsufficientBalance}
                className={`w-full mt-4 h-12 rounded-xl font-black text-[11px] uppercase tracking-[0.05em] transition-all shadow-xl active:scale-[0.98] text-white ${
                    isInsufficientBalance || numericPay <= 0 
                        ? 'bg-zinc-800 text-zinc-400 cursor-not-allowed border border-white/5' // Explicit disabled style
                        : tradeMode === 'algo' 
                        ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-500/20' 
                        : tradeMode === 'limit'
                        ? 'bg-blue-600 hover:bg-blue-500 shadow-blue-500/20'
                        : 'bg-emerald-600 hover:bg-emerald-500 shadow-emerald-500/10' 
                }`}
            >
              {isInsufficientBalance 
                ? 'Insufficient Balance' 
                : tradeMode === 'algo' 
                    ? 'LAUNCH TWAP STRATEGY' 
                    : tradeMode === 'limit' 
                        ? 'PLACE LIMIT ORDER' 
                        : numericPay <= 0 
                            ? 'Enter Amount' 
                            : 'Review Order'
              }
            </button>
          </div>

        </div>
      </section>

      {/* ---------------------------------------------------------------------------
          RIGHT PANEL: ANALYSIS & SAFETY
      --------------------------------------------------------------------------- */}
      <section className="lg:col-span-6 bg-zinc-900/40 border border-white/5 rounded-2xl p-6 flex flex-col h-full overflow-y-auto scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent">

          <div className="flex justify-between items-start mb-8">
            <div>
              <h2 className="text-lg font-bold text-white flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-gray-500" />
                {tradeMode === 'algo' ? 'Execution Simulation' : tradeMode === 'limit' ? 'Limit Intelligence' : 'Execution Analysis'}
              </h2>
            </div>
          </div>

          {/* LIMIT TAB CONTENT (AREA CHART) */}
          {tradeMode === 'limit' ? (
             <div className="flex-1 flex flex-col space-y-6">

                {/* 1. INTELLIGENCE GRID */}
                <div className="bg-black/40 border border-white/5 rounded-2xl p-6 relative overflow-hidden grid grid-cols-1 md:grid-cols-3 gap-6">
                   <EducationalTooltip 
                      title="Fill Probability" 
                      desc="AI-calculated likelihood of the price reaching your limit target within the set expiry time."
                   >
                        <div className="flex flex-col h-full justify-center">
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5"><Target size={12} className="text-gray-500" /> Probability</span>
                            <div className="flex items-baseline gap-2">
                                <span className="text-3xl font-mono font-bold text-white tabular-nums">{simulation.execProbability}%</span>
                                <span className={`text-[10px] font-black uppercase ${simulation.probColor}`}>{simulation.probLabel}</span>
                            </div>
                            <div className="w-full h-1 bg-zinc-800 rounded-full mt-2 overflow-hidden">
                                <div className={`h-full ${simulation.probColor.replace('text-', 'bg-')}`} style={{ width: `${simulation.execProbability}%` }}></div>
                            </div>
                        </div>
                   </EducationalTooltip>

                   <div className="flex flex-col border-l border-white/5 pl-6 h-full justify-center">
                      <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5"><Hourglass size={12} className="text-gray-500" /> Est. Time to Fill</span>
                      <span className="text-2xl font-mono font-bold text-white mt-1">{simulation.timeHorizon}</span>
                      <span className="text-[9px] text-zinc-500 mt-1 font-bold">Range: <span className="text-zinc-400">{simulation.timeRange}</span></span>
                   </div>

                   <EducationalTooltip 
                      title="Opportunity Cost (Drag)" 
                      desc="Estimated yield loss by locking assets in an order book."
                   >
                        <div className="flex flex-col border-l border-white/5 pl-6 h-full justify-center">
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5"><Coins size={12} className="text-gray-500" /> Capital Drag</span>
                            <span className={`text-2xl font-mono font-bold mt-1 tabular-nums ${simulation.dailyYieldLoss > 0.1 ? 'text-orange-500' : 'text-zinc-400'}`}>-{formatMoney(simulation.dailyYieldLoss)}</span>
                            <span className="text-[9px] text-zinc-500 mt-1">Daily yield loss (4.2% APY)</span>
                        </div>
                   </EducationalTooltip>
                </div>

                {/* 2. AREA CHART FOR DEPTH (STEPPED WALLS) */}
                <div className="flex-1 min-h-[200px] bg-black/20 border border-white/5 rounded-2xl p-6 relative flex flex-col">
                    <div className="flex justify-between items-start mb-4 relative z-10">
                        <div>
                            <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Projected Order Book</p>
                            <div className="flex items-center gap-2 mt-1">
                                <span className={`text-sm font-black uppercase ${simulation.structureColor}`}>{simulation.structureLabel}</span>
                            </div>
                        </div>
                        <div className="p-1.5 rounded-lg bg-zinc-800/50 border border-white/5 text-gray-500"><Layers size={14} /></div>
                    </div>

                    <div className="flex-1 w-full relative z-10 -ml-2 min-h-[140px]">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={depthData}>
                                <defs>
                                    <linearGradient id="bidGrad" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="0%" stopColor="#10b981" stopOpacity={0.4}/>
                                        <stop offset="100%" stopColor="#10b981" stopOpacity={0}/>
                                    </linearGradient>
                                    <linearGradient id="askGrad" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="0%" stopColor="#ef4444" stopOpacity={0.4}/>
                                        <stop offset="100%" stopColor="#ef4444" stopOpacity={0}/>
                                    </linearGradient>
                                </defs>
                                <XAxis 
                                    dataKey="price" 
                                    type="number"
                                    domain={['auto', 'auto']}
                                    axisLine={false} 
                                    tickLine={false} 
                                    tick={{ fill: '#52525b', fontSize: 9, fontWeight: 700 }}
                                    tickFormatter={(val) => val.toFixed(0)}
                                />
                                <YAxis hide />
                                <Tooltip cursor={{ stroke: '#ffffff', strokeWidth: 1, strokeDasharray: '4 4' }} contentStyle={{ backgroundColor: '#09090b', borderColor: '#333' }} />

                                {/* Stepped Line for Realistic Order Book Look */}
                                <Area type="stepAfter" dataKey="bidVol" stroke="#10b981" fill="url(#bidGrad)" strokeWidth={2} />
                                <Area type="stepAfter" dataKey="askVol" stroke="#ef4444" fill="url(#askGrad)" strokeWidth={2} />

                                {/* Current Price Line */}
                                <ReferenceLine x={ETH_PRICE} stroke="#71717a" strokeDasharray="3 3" label={{ position: 'top', value: 'MARKET', fill: '#71717a', fontSize: 9 }} />

                                {/* User Limit Price Line */}
                                <ReferenceLine x={parseFloat(limitPrice)} stroke="#3b82f6" strokeWidth={2} label={{ position: 'top', value: 'YOUR ORDER', fill: '#3b82f6', fontSize: 9, fontWeight: 'bold' }} />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                </div>
             </div>
          ) : tradeMode === 'algo' ? (
             <div className="flex-1 flex flex-col space-y-6">
                {/* ALGO COMPARISON */}
