                    <div className="flex flex-col items-center justify-center p-4 border border-zinc-800 rounded-xl bg-zinc-900/30">
                        <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest mb-2">Market Impact</span>
                        <span className="text-3xl font-mono font-bold text-red-500 mb-1 tabular-nums">-{simulation.swapImpactPct.toFixed(2)}%</span>
                        <span className="text-[10px] font-bold text-red-400/60 uppercase tabular-nums">Impact: -{formatMoney(simulation.swapImpactCost)}</span>
                    </div>

                    <EducationalTooltip 
                        title="Time-Weighted Average Price" 
                        desc="Breaks a large order into smaller 'child' orders executed over time."
                    >
                        <div className="flex flex-col items-center justify-center p-4 border border-purple-500/20 rounded-xl bg-purple-500/5 h-full">
                            <span className="text-[9px] font-black text-purple-400 uppercase tracking-widest mb-2">TWAP Strategy</span>
                            <span className="text-3xl font-mono font-bold text-green-500 mb-1 tabular-nums">~{simulation.algoTrancheImpactPct.toFixed(2)}%</span>
                            <span className="text-[10px] font-bold text-green-500/60 uppercase tabular-nums">Loss: -{formatMoney(simulation.algoTotalImpactCost)}</span>
                        </div>
                    </EducationalTooltip>

                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-10">
                        <EducationalTooltip 
                            title="Alpha Generation" 
                            desc="Profit generated by using algorithmic strategy vs market order."
                        >
                            <div className="bg-zinc-900 border border-white/10 px-4 py-2 rounded-full shadow-xl flex flex-col items-center">
                                <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Net Savings</span>
                                <span className={`text-lg font-mono font-black tabular-nums ${simulation.isAlgoEfficient ? 'text-green-500' : 'text-red-500'}`}>
                                {simulation.isAlgoEfficient ? '+' : ''}{formatMoney(simulation.netSavings)}
                                </span>
                            </div>
                        </EducationalTooltip>
                    </div>
                </div>

                {/* SCHEDULE CHART */}
                <div className="flex-1 min-h-[200px] bg-black/20 border border-white/5 rounded-2xl p-6 flex flex-col">
                   <div className="flex justify-between items-center mb-6">
                      <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Execution Schedule</span>
                      <div className="flex items-center gap-3">
                         <span className="text-[9px] font-mono text-zinc-600">Interval: ~{simulation.avgIntervalMins}m</span>
                      </div>
                   </div>
                   <div className="flex-1 w-full min-h-[150px]">
                      <ResponsiveContainer width="100%" height="100%">
                         <BarChart data={simulation.scheduleData}>
                            <XAxis 
                               dataKey="time" 
                               axisLine={false} 
                               tickLine={false} 
                               tick={{ fill: '#52525b', fontSize: 10, fontWeight: 700 }} 
                               interval={2}
                            />
                            <Tooltip cursor={{ fill: 'rgba(255,255,255,0.05)' }} contentStyle={{ backgroundColor: '#09090b', borderColor: '#333' }} />
                            <Bar dataKey="volume" radius={[4, 4, 0, 0]}>
                               {simulation.scheduleData.map((entry, index) => (
                                  <Cell 
                                    key={`cell-${index}`} 
                                    fill={entry.status === 'executed' ? '#3f3f46' : entry.status === 'active' ? '#a855f7' : 'transparent'}
                                    stroke={entry.status === 'pending' ? '#a855f7' : 'none'}
                                    strokeWidth={1}
                                    strokeDasharray={entry.status === 'pending' ? '4 4' : '0'}
                                  />
                               ))}
                            </Bar>
                         </BarChart>
                      </ResponsiveContainer>
                   </div>
                </div>
             </div>
          ) : (
             <>
                {/* Top Block: Routing Efficiency */}
                <div className="mb-6">
                    <div className="flex items-end gap-4 mb-2">
                    <span className="text-6xl font-mono font-bold text-white tracking-tighter tabular-nums">{simulation.routingScore}</span>
                    <div className="flex flex-col mb-2">
                        <span className="text-emerald-500 font-bold uppercase text-xs tracking-wider">Optimal</span>
                        <span className="text-gray-500 text-[10px] uppercase">0-10 Scale</span>
                    </div>
                    </div>
                    {/* Progress Bar */}
                    <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden relative">
                    <div className="absolute top-0 left-0 h-full bg-emerald-500 w-[99%] rounded-full shadow-[0_0_15px_rgba(16,185,129,0.6)]" />
                    </div>
                    <div className="mt-4 flex items-center gap-2 text-xs text-gray-400">
                    <Zap className="w-3.5 h-3.5 text-gray-500" />
                    <span>Route optimization vs. direct pool: <span className="text-white font-medium">0.05% better</span></span>
                    </div>
                </div>

                {/* BOTTOM SECTION - THE FIX */}
                {/* Use grid-cols-1 to force vertical stacking. Only 2 columns on HUGE screens (2xl) */}
                <div className="grid grid-cols-1 2xl:grid-cols-2 gap-4 mt-auto">

                    {/* 1. Smart Route Execution */}
                    <div className="bg-zinc-900/40 border border-white/5 rounded-xl p-4 flex flex-col min-h-[160px]">
                    <div className="flex items-center justify-between mb-3">
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide flex items-center gap-2">
                        <GitMerge className="w-3 h-3" /> Smart Route
                        </span>
                        <span className="text-[10px] bg-zinc-800 text-gray-400 px-1.5 py-0.5 rounded border border-white/5">HOP: ETH → USDC</span>
                    </div>

                    {/* MEV Badge - No Absolute positioning */}
                    <div className="flex items-center gap-2 mb-3 bg-emerald-500/5 border border-emerald-500/20 rounded px-2 py-1.5">
                        <ShieldCheck className="w-3 h-3 text-emerald-500" />
                        <span className="text-[10px] font-medium text-emerald-500 uppercase">MEV Protection Active</span>
                        <span className="ml-auto text-[10px] text-emerald-500/50">Private RPC</span>
                    </div>

                    <div className="flex flex-col gap-2 mt-auto">
                        {simulation.routeSplit.slice(0, 2).map((route) => (
                            <div key={route.dex} className="space-y-1">
                                <div className="flex justify-between text-[10px] text-gray-400 uppercase"><span>{route.dex}</span><span className="text-white">{route.pct}%</span></div>
                                <div className="h-1 w-full bg-gray-800 rounded-full">
                                    <div className={`h-full ${route.color === 'bg-white' ? 'bg-white' : 'bg-gray-600'} rounded-full`} style={{ width: `${route.pct}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                    </div>

                    {/* 2. Cost Structure */}
                    <div className="bg-zinc-900/40 border border-white/5 rounded-xl p-4 flex flex-col min-h-[160px]">
                    <div className="flex items-center gap-2 mb-4">
                        <Coins className="w-3 h-3 text-gray-500" />
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Cost Structure</span>
                    </div>

                    <div className="flex flex-col gap-2 mt-auto text-xs">
                        <div className="flex justify-between"><span className="text-gray-500">Max Slippage</span><span className="text-gray-300">Auto ({simulation.liquidityBuffer})</span></div>
                        <div className="flex justify-between"><span className="text-gray-500">Network Fee</span><span className="text-white font-mono tabular-nums">~{formatMoney(BASE_GAS_COST_USD)}</span></div>
                        <div className="flex justify-between"><span className="text-gray-500">Price Impact</span><span className="text-red-400 font-mono tabular-nums">-{simulation.swapImpactPct.toFixed(2)}%</span></div>
                        <div className="h-px bg-white/5 my-1"></div>
                        <div className="flex justify-between text-sm"><span className="text-gray-300">Total Cost</span><span className="text-white font-bold font-mono tabular-nums">{formatMoney(simulation.totalSwapCost)}</span></div>
                    </div>
                    </div>

                </div>
             </>
          )}

      </section>
    </div>
  );
};

